using System.Diagnostics;
using System.Text.Json;
using RAWSelectionAssistant.Core.Services.Projects;
using RAWSelectionAssistant.Core.Services.Color;
namespace RAWSelectionAssistant.Tests;
[TestClass]public sealed class R53InteractionTests
{
 [TestMethod]public async Task SustainedInputPublishesIntermediateAndLatestWithBoundedConcurrency()
 {
  var output=Environment.GetEnvironmentVariable("KITAO_R53_INTERACTION");var clock=Stopwatch.StartNew();var frames=new List<(long Rev,int Value,double Ms)>();int active=0,max=0;var queue=new LatestPreviewQueue<int,int>(async(value,token)=>{var n=Interlocked.Increment(ref active);max=Math.Max(max,n);try{await Task.Delay(180,token);return value;}finally{Interlocked.Decrement(ref active);}},(rev,value,result)=>frames.Add((rev,result,clock.Elapsed.TotalMilliseconds)));
  for(int i=0;i<100;i++){queue.Submit(i);await Task.Delay(20);}var during=frames.Count;await queue.Work;Assert.AreEqual(1,max);Assert.IsTrue(during>=2);Assert.IsTrue(frames[0].Ms<1000);Assert.AreEqual(99,frames[^1].Value);Assert.IsTrue(frames.Zip(frames.Skip(1),(a,b)=>a.Rev<b.Rev).All(x=>x));int count=frames.Count;queue.Submit(1000);queue.Invalidate();await queue.Work;Assert.AreEqual(count,frames.Count);if(output is not null){Directory.CreateDirectory(output);File.WriteAllText(Path.Combine(output,"SCHEDULER.json"),JsonSerializer.Serialize(new{firstFrameMs=frames[0].Ms,duringFrames=during,total=frames.Count,maxConcurrency=max,last=frames[^1].Value,frames=frames.Select(x=>new{x.Rev,x.Value,x.Ms}),scope="180ms reproducible worker under20ms continuous2s input; scheduler not physical pointer"},new JsonSerializerOptions{WriteIndented=true}));}
 }
 [TestMethod]public async Task ContextInvalidationRetiresOldJobBeforeStartingLatestContext()
 {
  int active=0,maximum=0;var values=new List<int>();var queue=new LatestPreviewQueue<int,int>(async(v,t)=>{maximum=Math.Max(maximum,Interlocked.Increment(ref active));try{await Task.Delay(100,t);return v;}finally{Interlocked.Decrement(ref active);}},(_,v,r)=>values.Add(r));queue.Submit(1);await Task.Delay(20);queue.Invalidate();queue.Submit(2);queue.Submit(3);await queue.Work;CollectionAssert.AreEqual(new[]{3},values);Assert.AreEqual(1,maximum);
 }
 [TestMethod]public void FastPreviewUsesSameDefinitionAndRecordsApproximationDifference()
 {
  var output=Environment.GetEnvironmentVariable("KITAO_R53_INTERACTION");var master=R53ProfessionalLocalTests.Master(1200,800);var node=new ColorAdjustmentStackNode(Guid.NewGuid(),ColorStudioNodeType.BasicTone,"local",NumericParameters:new Dictionary<string,double>{{"exposure",.5}}){CompositeVersion=1,Opacity=.6,LocalMask=new([new([new(.2,.3),new(.7,.6)],.1,.5,.7,1)])};var d=new ProfessionalRawDefinition{LocalEdits=new(new([node],ProcessingVersion:2))};var json=JsonSerializer.Serialize(d);var clock=Stopwatch.StartNew();using var fast=ProfessionalRawLocalRenderer.Fast(master,d);var fastMs=clock.Elapsed.TotalMilliseconds;clock.Restart();using var fine=ProfessionalRawPipeline.RenderPreview(master,d,800);var fineMs=clock.Elapsed.TotalMilliseconds;var errors=fast.Rgb32.ToArray().Zip(fine.Rgb32.ToArray(),(a,b)=>Math.Abs(a-b)*255).Order().ToArray();var mean=errors.Average();var p95=errors[(int)(errors.Length*.95)];var maximum=errors[^1];Assert.AreEqual(json,JsonSerializer.Serialize(d));Assert.IsTrue(double.IsFinite(mean));Assert.IsTrue(mean<=1.5&&p95<=4&&maximum<=32,"Fixed approximation budget, never widened after measurements");if(output is not null){Directory.CreateDirectory(output);File.WriteAllText(Path.Combine(output,"APPROXIMATION.json"),JsonSerializer.Serialize(new{width=1200,height=800,fastMs,fineMs,mean,p95,maximum,targetMean=1.5,targetP95=4,targetMax=32,withinTarget=mean<=1.5&&p95<=4&&maximum<=32,input="Synthetic high-frequency RGB; intentionally stresses nearest vs area",notPixelEqual=true},new JsonSerializerOptions{WriteIndented=true}));}
 }
 [TestMethod]public async Task ContinuousComplexMaskWorkerPublishesBeforePenStops()
 {
  var output=Environment.GetEnvironmentVariable("KITAO_R53_INTERACTION");var strokes=Enumerable.Range(0,20).Select(n=>new StudioMaskStroke(Enumerable.Range(0,1000).Select(i=>new StudioMaskPoint(.05+.9*i/999,.5+.35*Math.Sin(i*.01+n))).ToArray(),.025,.5,.5,1)).ToArray();var mask=new StudioLocalMask(strokes).Freeze();var clock=Stopwatch.StartNew();var frames=new List<(int Value,double Ms)>();int active=0,max=0;var queue=new LatestPreviewQueue<int,double>(async(value,token)=>await Task.Run(()=>{var n=Interlocked.Increment(ref active);max=Math.Max(max,n);try{var pixels=StudioMaskRaster.Alpha(mask,1.5,512,342,token);return pixels.Sum(x=>(double)x)+value;}finally{Interlocked.Decrement(ref active);}},token),(rev,value,result)=>frames.Add((value,clock.Elapsed.TotalMilliseconds)));
  for(int i=0;i<100;i++){queue.Submit(i);await Task.Delay(20);}int during=frames.Count;await queue.Work;Assert.AreEqual(1,max);Assert.IsTrue(frames[0].Ms<1000,"Fixed first-frame budget");Assert.IsTrue(during>=2,"Must publish during continuous stroke, not only on stop");Assert.AreEqual(99,frames[^1].Value);if(output is not null)File.WriteAllText(Path.Combine(output,"COMPLEX_OVERLAY.json"),JsonSerializer.Serialize(new{sourceWidth=6000,sourceHeight=4000,strokes=20,points=20000,firstFrameMs=frames[0].Ms,duringFrames=during,total=frames.Count,last=frames[^1].Value,maxConcurrency=max,scope="Actual compiled mask sampler under continuous inputs; not physical pointer"},new JsonSerializerOptions{WriteIndented=true}));
 }
 [TestMethod]public void PinnedSceneExposureScalarReferencesMatchVersionedStage()
 {
  var path=Environment.GetEnvironmentVariable("KITAO_R53_SCENE_REFERENCE");if(path is null){Assert.Inconclusive("Pinned independently executed scalar reference required");return;}using var doc=JsonDocument.Parse(File.ReadAllText(path));foreach(var row in doc.RootElement.GetProperty("cases").EnumerateArray()){var input=row.GetProperty("input").GetDouble();var ev=row.GetProperty("ev").GetDouble();var actual=new SceneExposureV1(ev).Apply(new(input,input,input),1);Assert.AreEqual(row.GetProperty("darktable").GetDouble(),actual.X,1e-5);Assert.AreEqual(row.GetProperty("rawtherapee").GetDouble(),actual.X,1e-5);}
 }
 [TestMethod]public void ParallelRowBandsKeepSameExactPixelsAsSharedFullFrame()
 {
  var data=Enumerable.Range(0,96*64*3).Select(i=>(float)((i%91)/100d)).ToArray();using var input=new HighBitDepthImageBuffer(96,64,data,"16");var node=new ColorAdjustmentStackNode(Guid.NewGuid(),ColorStudioNodeType.BasicTone,"exact",NumericParameters:new Dictionary<string,double>{{"exposure",.35}}){CompositeVersion=1,Opacity=.7,LocalMask=new([new([new(.1,.2),new(.8,.7)],.1,.5,.6,1)])};var stack=new ColorAdjustmentStack([node,node with{Id=Guid.NewGuid(),Blend=StudioLayerBlend.Screen}],ProcessingVersion:2);var analysis=ColorStudioProcessingAnalysis.Create(new RAWSelectionAssistant.Core.Services.AssetLibrary.VisualAnalysis.VisualPixelBuffer(1,1,new byte[3]),stack,null);using var expected=new ColorStudioRenderPipeline().Render(input,analysis,null,stack,captureNodeDiagnostics:false).ProcessingPixels!;using var actual=BoundedLegacyRawRenderer.Render(input,null,stack,null);CollectionAssert.AreEqual(expected.Rgb32.ToArray(),actual.Rgb32.ToArray());
 }
 [TestMethod]public void SceneExposurePreservesLinearRatiosAndNegativeHighRangeWithoutChangingOldDefinitions()
 {
  var local=new SceneExposureV1(-2);var v=local.Apply(new(-.2,.5,4),1);Assert.AreEqual(-.05,v.X,1e-12);Assert.AreEqual(.125,v.Y,1e-12);Assert.AreEqual(1,v.Z,1e-12);var m=R53ProfessionalLocalTests.Master(60,40);var old=new ProfessionalRawDefinition();Assert.IsFalse(JsonSerializer.Serialize(old).Contains("SceneExposure"));var d=old with{SceneExposure=new(-2,new([new([new(.5,.5)],.4,.5,1,1)]))};using var a=ProfessionalRawPipeline.Render(m,old);using var b=ProfessionalRawPipeline.Render(m,d);Assert.IsFalse(a.Rgb32.Span.SequenceEqual(b.Rgb32.Span));var back=JsonSerializer.Deserialize<ProfessionalRawDefinition>(JsonSerializer.Serialize(d))!;using var reopened=ProfessionalRawPipeline.Render(m,back);CollectionAssert.AreEqual(b.Rgb32.ToArray(),reopened.Rgb32.ToArray());CollectionAssert.AreEqual(a.Rgb32.ToArray(),ProfessionalRawPipeline.Render(m,old).Rgb32.ToArray());
 }
}
